class PriceUnitObjection127(unittest.TestCase):
    def check_neighbor(self, case):
        _,messages,known,_=ext._parse(case['ctx'])
        text='\n'.join(m['body'] for m in messages if m['direction']=='in')
        answer=prices.answer(messages,known,text);reply=answer.get('reply','');expect=case['expect']
        consent=prices.consent(messages)
        if 'prior_verified' in expect:
            self.assertEqual(prices.prior_quote_verified(messages,known,consent),expect['prior_verified'])
        if 'consent' in expect:self.assertEqual(consent['status'],expect['consent'])
        if 'price_current' in expect:self.assertEqual(prices.asks_current(messages),expect['price_current'])
        for term in expect.get('reply_contains',[]):self.assertIn(term,reply)
        if expect.get('numeric') is False:self.assertFalse(answer.get('amounts'))
        for field in expect.get('known_fields',[]):self.assertEqual(qs.inspect(messages)[field]['status'],'answered')
        if expect.get('no_service_minimum') or expect.get('no_stale_800'):self.assertNotIn(800,answer.get('amounts',[]))
        if expect.get('numeric_kind')=='minimum_per_metre':self.assertIn('от 800 рублей за метр',reply)
        if expect.get('numeric_kind')=='minimum_service':
            self.assertIn('от 800 рублей',reply);self.assertNotIn('за метр',reply)

    def check_guard(self, case):
        consent=prices.consent(case['messages'])
        self.assertEqual(prices.prior_quote_verified(case['messages'],dict(direction='mnc',city='Елец'),consent),case['expect_verified'])

def neighbor_test(case):
    def test(self):self.check_neighbor(case)
    return test
def guard_test(case):
    def test(self):self.check_guard(case)
    return test
for case in NEIGHBORS:setattr(PriceUnitObjection127,'test_'+case['id'],neighbor_test(case))
for case in GUARDS:setattr(PriceUnitObjection127,'test_'+case['id'],guard_test(case))
